-- Changeset db/changelog/changes/conf/0.1.4/0.1.4_con_002.yaml::con-change-0.1.4-002::limit
-- Afegir paràmetres per configurar els timeouts HTTP dels clients RestTemplate
INSERT INTO com_PARAMETRE (GRUP, SUBGRUP, TIPUS, CODI, NOM, DESCRIPCIO, VALOR, EDITABLE) VALUES ('General', 'HTTP', 'NUMERIC', 'es.caib.comanda.http.connect.timeout.seconds', 'Timeout de connexió HTTP (segons)', 'Temps màxim d''espera en segons per establir una connexió HTTP amb serveis externs (per exemple: comprovacions de salut, refresc d''informació, logs, estadístiques o DIR3). Un valor massa baix pot provocar errors falsos en xarxes lentes; un valor massa alt pot mantenir fils ocupats quan un servidor no respon. Un valor menor o igual a 0 desactiva el límit (no recomanat, pot bloquejar el pool de fils indefinidament).', '5', 1);

INSERT INTO com_PARAMETRE (GRUP, SUBGRUP, TIPUS, CODI, NOM, DESCRIPCIO, VALOR, EDITABLE) VALUES ('General', 'HTTP', 'NUMERIC', 'es.caib.comanda.http.read.timeout.short.seconds', 'Timeout de lectura HTTP curt (segons)', 'Temps màxim d''espera de lectura en segons per a peticions HTTP ràpides (per exemple: comprovacions periòdiques de salut). Un valor massa baix pot generar falsos positius d''estat "Caiguda"; un valor massa alt pot saturar els fils d''execució i retenir connexions de base de dades si un servei o proxy queda penjat. Un valor menor o igual a 0 desactiva el límit (no recomanat, pot bloquejar el monitoratge de salut).', '10', 1);

INSERT INTO com_PARAMETRE (GRUP, SUBGRUP, TIPUS, CODI, NOM, DESCRIPCIO, VALOR, EDITABLE) VALUES ('General', 'HTTP', 'NUMERIC', 'es.caib.comanda.http.read.timeout.medium.seconds', 'Timeout de lectura HTTP mitjà (segons)', 'Temps màxim d''espera de lectura en segons per a peticions HTTP estàndard (per exemple: comprovació d''URL, refresc d''informació d''aplicacions, llistat i previsualització de logs, DIR3 o autenticació). Un valor massa baix pot interrompre peticions vàlides; un valor massa alt pot mantenir peticions i fils bloquejats davant serveis o proxies caiguts. Un valor menor o igual a 0 desactiva el límit (no recomanat).', '60', 1);

INSERT INTO com_PARAMETRE (GRUP, SUBGRUP, TIPUS, CODI, NOM, DESCRIPCIO, VALOR, EDITABLE) VALUES ('General', 'HTTP', 'NUMERIC', 'es.caib.comanda.http.read.timeout.long.seconds', 'Timeout de lectura HTTP llarg (segons)', 'Temps màxim d''espera de lectura en segons per a peticions HTTP pesades (per exemple: sincronització d''estadístiques o descàrrega de logs). Un valor massa baix pot tallar càrregues o descàrregues llargues; un valor massa alt pot mantenir fils ocupats durant molt de temps si el servei o proxy no respon. Un valor menor o igual a 0 desactiva el límit (utilitzeu-ho amb precaució, pot deixar fils bloquejats indefinidament).', '600', 1);

-- Changeset db/changelog/changes/conf/0.1.4/0.1.4_con_002.yaml::con-change-0.1.4-003::limit
-- Destacar amb ALERTA els avisos a les descripcions dels paràmetres de timeout HTTP
UPDATE com_PARAMETRE SET DESCRIPCIO = 'Temps màxim d''espera en segons per establir una connexió HTTP amb serveis externs (per exemple: comprovacions de salut, refresc d''informació, logs, estadístiques o DIR3). ALERTA: Un valor massa baix pot provocar errors falsos en xarxes lentes; un valor massa alt pot mantenir fils ocupats quan un servidor no respon. Un valor menor o igual a 0 desactiva el límit (no recomanat, pot bloquejar el pool de fils indefinidament).' WHERE CODI = 'es.caib.comanda.http.connect.timeout.seconds';

UPDATE com_PARAMETRE SET DESCRIPCIO = 'Temps màxim d''espera de lectura en segons per a peticions HTTP ràpides (per exemple: comprovacions periòdiques de salut). ALERTA: Un valor massa baix pot generar falsos positius d''estat "Caiguda"; un valor massa alt pot saturar els fils d''execució i retenir connexions de base de dades si un servei o proxy queda penjat. Un valor menor o igual a 0 desactiva el límit (no recomanat, pot bloquejar el monitoratge de salut).' WHERE CODI = 'es.caib.comanda.http.read.timeout.short.seconds';

UPDATE com_PARAMETRE SET DESCRIPCIO = 'Temps màxim d''espera de lectura en segons per a peticions HTTP estàndard (per exemple: comprovació d''URL, refresc d''informació d''aplicacions, llistat i previsualització de logs, DIR3 o autenticació). ALERTA: Un valor massa baix pot interrompre peticions vàlides; un valor massa alt pot mantenir peticions i fils bloquejats davant serveis o proxies caiguts. Un valor menor o igual a 0 desactiva el límit (no recomanat).' WHERE CODI = 'es.caib.comanda.http.read.timeout.medium.seconds';

UPDATE com_PARAMETRE SET DESCRIPCIO = 'Temps màxim d''espera de lectura en segons per a peticions HTTP pesades (per exemple: sincronització d''estadístiques o descàrrega de logs). ALERTA: Un valor massa baix pot tallar càrregues o descàrregues llargues; un valor massa alt pot mantenir fils ocupats durant molt de temps si el servei o proxy no respon. Un valor menor o igual a 0 desactiva el límit (utilitzeu-ho amb precaució, pot deixar fils bloquejats indefinidament).' WHERE CODI = 'es.caib.comanda.http.read.timeout.long.seconds';

-- Changeset db/changelog/changes/conf/0.1.4/0.1.4_con_003.yaml::con-change-0.1.4-004::limit
-- Afegir paràmetre per activar o desactivar la recol·lecció en memòria de mètriques de rendiment
INSERT INTO com_PARAMETRE (GRUP, SUBGRUP, TIPUS, CODI, NOM, DESCRIPCIO, VALOR, EDITABLE) VALUES ('Monitor', 'Rendiment', 'BOOLEAN', 'es.caib.comanda.monitor.rendiment.actiu', 'Activar recol·lecció de mètriques de rendiment', 'Activa el mostreig periòdic en memòria (cada 1 s, fins a 1 h) de les mètriques internes de rendiment (pools de BD, workers i cues JMS). En desactivar-lo s''atura la recol·lecció i s''esborra tot l''històric acumulat en memòria.', 'true', 1);
